<script setup lang="ts">
import { ref, computed, nextTick, onMounted, onBeforeUnmount, watch } from 'vue'
import Viewport from './Viewport.vue'
import CustomThumbnail from './CustomThumbnail.vue'
import { state, customEditing, customEditingId, beginCustomObject, saveCustomObject, cancelCustomObject, insertCustomObject, selected, selection, selectObject, canGroup, groupSelected, ungroupSelected, collisionSelection, history, checkpoint, add, duplicate, copySelection, pasteSelection, remove, edit, undo, redo, save, load, createRoom, editRoom, toggleBaseboard, toggleCollisions, editStructuralColor, editFloorColor, editProjectName, FLOOR_COLOR, WALL_COLOR, isStructural, isOpening, type ObjectKind } from './editor'
const viewport=ref<InstanceType<typeof Viewport>>();const file=ref<HTMLInputElement>();const currentView=ref('Perspectiva')
const libraryOpen=ref(false),libraryDialog=ref<HTMLDialogElement>(),libraryError=ref(''),customName=ref(state.customObjects.find(entry=>entry.id===customEditingId.value)?.name??''),previousView=ref('Perspectiva')
watch(libraryOpen,async open=>{await nextTick();if(open&&!libraryDialog.value?.open)libraryDialog.value?.showModal();else if(!open&&libraryDialog.value?.open)libraryDialog.value.close()})
function openCustomLibrary(){libraryError.value='';libraryOpen.value=true;paletteOpen.value=false}
function startCustom(id?:string){const name=state.customObjects.find(entry=>entry.id===id)?.name??'';if(!beginCustomObject(id))return;libraryOpen.value=false;roomEditorOpen.value=false;customName.value=name;previousView.value=currentView.value;currentView.value='Perspectiva'}
function finishCustom(){if(saveCustomObject(customName.value)){currentView.value=previousView.value;openCustomLibrary()}}
function leaveCustom(){cancelCustomObject();currentView.value=previousView.value;openCustomLibrary()}
function insertCustom(id:string){if(insertCustomObject(id))libraryOpen.value=false;else{libraryError.value=state.error;state.error=''}}
const editingProjectName=ref(false),projectNameDraft=ref(''),projectNameInput=ref<HTMLInputElement>()
async function startProjectNameEdit(){projectNameDraft.value=state.projectName;editingProjectName.value=true;await nextTick();projectNameInput.value?.focus();projectNameInput.value?.select()}
function saveProjectName(){if(!projectNameDraft.value.trim())return;editProjectName(projectNameDraft.value);editingProjectName.value=false}
// Temporarily hidden toolbar switches; restore them in a future UI step.
const showToolbarCheckboxes=false
const roomEditorOpen=ref(false)
function toggleRoomEditor(){roomEditorOpen.value=!roomEditorOpen.value;paletteOpen.value=false}
watch(()=>state.room,room=>{if(!room)roomEditorOpen.value=false})
const paletteOpen=ref(false),colorControl=ref<HTMLElement>()
const paletteColors=[{name:'Blanco',value:'#f2f1ed'},{name:'Arena',value:'#d1c8ba'},{name:'Beige',value:'#e4d5c8'},{name:'Terracota',value:'#ad5b20'},{name:'Teja',value:'#915845'},{name:'Azul claro',value:'#bbcbd0'},{name:'Azul grisáceo',value:'#68858f'},{name:'Oliva',value:'#929879'},{name:'Gris',value:'#85867e'},{name:'Topo',value:'#9e897c'},{name:'Malva',value:'#77596e'}]
const surfaceColorTarget=ref<'walls'|'floor'>('walls')
const floorPalette=computed(()=>structurePalette.value&&surfaceColorTarget.value==='floor')
const structurePalette=computed(()=>!customEditing.value&&(!selected.value||isStructural(selected.value)))
const paletteEnabled=computed(()=>structurePalette.value||!!selected.value&&selected.value.type!=='group')
const paletteColor=computed(()=>floorPalette.value?(state.room?.floorColor??FLOOR_COLOR):structurePalette.value?state.structuralColor:selected.value?.color)
function applyPaletteColor(color:string){if(floorPalette.value)editFloorColor(color);else if(structurePalette.value)editStructuralColor(color);else edit('color',color)}
function resetPaletteColor(){applyPaletteColor(floorPalette.value?FLOOR_COLOR:structurePalette.value?WALL_COLOR:selected.value?.type==='door'?'#b78b61':selected.value?.type==='window'?'#7faec6':'#779b8e')}
function dismissPalette(e:PointerEvent){if(!colorControl.value?.contains(e.target as Node))paletteOpen.value=false}
watch(()=>state.selected,()=>paletteOpen.value=false)
const roomFields:{key:'width'|'depth'|'height';label:string}[]=[{key:'width',label:'Anchura'},{key:'depth',label:'Profundidad'},{key:'height',label:'Altura'}]
const additions:{type:ObjectKind;label:string;icon:string}[]=[{type:'door',label:'Puerta',icon:'▯'},{type:'window',label:'Ventana',icon:'⊞'},{type:'column',label:'Columna',icon:'▥'},{type:'beam',label:'Viga',icon:'━'}]
const visibleObjects=computed(()=>state.objects.filter(object=>roomEditorOpen.value===additions.some(item=>item.type===object.type)))
const editableObjectIds=computed(()=>visibleObjects.value.map(object=>object.id))
watch([editableObjectIds,selection],()=>{if(selection.value.some(object=>!editableObjectIds.value.includes(object.id)))selectObject('')})
const icons:Record<ObjectKind,string>={box:'◇',cylinder:'◯',door:'▯',window:'⊞',column:'▥',beam:'━',group:'▣'}
function changeCollisions(e:Event){toggleCollisions();(e.target as HTMLInputElement).checked=collisionSelection.value.checked;(e.target as HTMLInputElement).indeterminate=collisionSelection.value.mixed}
function resetInput(e:Event,value:unknown){(e.target as HTMLInputElement).value=String(value??'')}
function resetRoomInput(e:Event,key:'width'|'depth'|'height'|'thickness'){resetInput(e,state.room?.[key])}
function input(e:Event){return (e.target as HTMLInputElement).value}
function changeView(){viewport.value?.view(currentView.value)}
function textTarget(target:EventTarget|null){return target instanceof HTMLElement&&!!target.closest('input,select,textarea,[contenteditable]:not([contenteditable="false"])')}
function pasteTypes():ObjectKind[]{return roomEditorOpen.value?additions.map(item=>item.type):['box','cylinder','group']}
function copyEvent(e:ClipboardEvent){if(libraryOpen.value||textTarget(e.target))return;if(copySelection()){e.preventDefault();e.clipboardData?.setData('text/plain',selection.value.map(object=>object.name).join('\n'))}}
function pasteEvent(e:ClipboardEvent){if(libraryOpen.value||textTarget(e.target))return;e.preventDefault();pasteSelection(pasteTypes())}
function key(e:KeyboardEvent){
 if(libraryOpen.value)return
 if(e.key==='Escape'&&paletteOpen.value){paletteOpen.value=false;e.preventDefault();return}
 if(e.key==='Escape'&&roomEditorOpen.value){roomEditorOpen.value=false;e.preventDefault();return}
 if(textTarget(e.target))return
 const command=e.ctrlKey||e.metaKey,key=e.key.toLowerCase()
 if(command&&!e.altKey){
  if(key==='z'){e.preventDefault();e.shiftKey?redo():undo();return}
  if(key==='d'){e.preventDefault();duplicate();return}
  if(key==='c'){copySelection();return}
  if(key==='v'){e.preventDefault();pasteSelection(pasteTypes());return}
 }
 if(!command&&!e.altKey){
  if(key==='r'&&selected.value&&!isOpening(selected.value))state.transformMode='rotate'
  if(key==='w')state.transformMode='translate'
  if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove()}
 }
 if(e.key==='Escape')selectObject('')
}
watch(selected,object=>{if(!object||isOpening(object))state.transformMode='translate'})
onMounted(()=>{window.addEventListener('keydown',key);window.addEventListener('copy',copyEvent);window.addEventListener('paste',pasteEvent);window.addEventListener('pointerdown',dismissPalette)});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);window.removeEventListener('copy',copyEvent);window.removeEventListener('paste',pasteEvent);window.removeEventListener('pointerdown',dismissPalette)})
</script>
<template>
<div class="app"><header><a class="brand" href="/">▦ <span>gridly<span class="dot">.</span></span></a><div v-if="!customEditing" class="project-name"><form v-if="editingProjectName" class="project-name-editor" @submit.prevent="saveProjectName"><input ref="projectNameInput" v-model="projectNameDraft" aria-label="Nombre del proyecto" maxlength="120" required @keydown.esc.stop="editingProjectName=false"><button type="submit" class="project-name-save" aria-label="Guardar nombre del proyecto" title="Guardar nombre del proyecto" :disabled="!projectNameDraft.trim()"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M5 3h12l4 4v14H3V3h2Z"/><path d="M7 3v6h9V3M7 21v-8h10v8"/></svg></button></form><button v-else class="project-name-button" title="Editar nombre del proyecto" @click="startProjectNameEdit">{{state.projectName}}</button></div><form v-else class="custom-name-editor" @submit.prevent="finishCustom"><input v-model="customName" aria-label="Nombre del objeto personalizado" placeholder="Nombre del objeto" maxlength="120" required><button type="submit" class="primary" :disabled="!customName.trim()||!state.objects.length">Guardar objeto</button><button type="button" @click="leaveCustom">Volver a la habitación</button></form><div v-if="!customEditing" class="header-actions"><button @click="file?.click()">Abrir</button><button class="primary" @click="save">↓ Descargar proyecto</button><input ref="file" hidden type="file" accept=".json" @change="e=>{const f=(e.target as HTMLInputElement).files?.[0];if(f)load(f);(e.target as HTMLInputElement).value=''}"></div></header>
<div class="workspace"><aside class="objects-panel"><section class="sidebar-card add-shapes-card" :aria-label="customEditing?'Formas':roomEditorOpen?'Construcción':'Muebles'"><div class="construction-title">{{customEditing?'FORMAS':roomEditorOpen?'CONSTRUCCIÓN':'MUEBLES'}}</div><div class="construction-buttons"><template v-if="roomEditorOpen"><button v-for="item in additions" :key="item.type" :disabled="(item.type==='door'||item.type==='window')&&!state.room" @click="add(item.type)"><span>{{item.icon}}</span> {{item.label}}</button><button class="baseboard-button" :disabled="!state.room" :aria-pressed="!!state.room?.baseboard" @click="toggleBaseboard"><span>▰</span> {{state.room?.baseboard?'Quitar rodapié':'Rodapié'}}</button></template><template v-else><button v-if="!state.room && !customEditing" @click="createRoom">＋ Crear habitación</button><button @click="add('box')"><span>◇</span> Prisma</button><button @click="add('cylinder')"><span>◯</span> Cilindro</button><button v-if="!customEditing" class="custom-shape-button" @click="openCustomLibrary"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="m4 20 12-12 4 4L8 24M15 3v3M21 6h-3M6 5v4M4 7h4M19 18v4M17 20h4" transform="translate(0 -2)"/></svg><span>Personalizado</span></button></template></div></section><section class="sidebar-card existing-shapes-card" aria-label="Elementos incluidos"><div class="construction-title">ELEMENTOS</div><div class="object-list"><button v-for="o in visibleObjects" :key="o.id" :class="['object-row',{active:selection.some(item=>item.id===o.id)}]" @click="e=>selectObject(o.id,e.ctrlKey||e.metaKey||e.shiftKey)"><span class="object-icon">{{icons[o.type??'box']}}</span><span>{{o.name}}</span><span class="swatch" :style="{background:o.color}"></span></button><p v-if="!visibleObjects.length" class="muted">{{customEditing?'No hay formas añadidas.':roomEditorOpen?'No hay elementos de construcción.':'No hay muebles añadidos.'}}</p></div></section></aside>
<main><div class="canvas-wrap"><Viewport ref="viewport" :editable-object-ids="editableObjectIds" :workshop="customEditing"/><div class="toolbar" role="toolbar" aria-label="Herramientas del plano"><div class="toolbar-group"><button aria-label="Deshacer" title="Deshacer (Ctrl+Z)" :disabled="!history.undo" @click="undo"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="square" stroke-linejoin="miter"><path d="M4 12a8 8 0 1 1 2.3 5.7"/><path d="m1 9 3 3 3-3"/></svg></button><button aria-label="Rehacer" title="Rehacer (Ctrl+Mayús+Z)" :disabled="!history.redo" @click="redo"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="square" stroke-linejoin="miter"><g transform="translate(24 0) scale(-1 1)"><path d="M4 12a8 8 0 1 1 2.3 5.7"/><path d="m1 9 3 3 3-3"/></g></svg></button></div><span class="separator" aria-hidden="true"></span><div class="toolbar-group"><button class="group-action" :disabled="!selection.length" @click="duplicate" title="Duplicar selección (Ctrl/Cmd+D)">Duplicar</button><button class="group-action" :disabled="!canGroup" @click="groupSelected" title="Agrupar selección">Agrupar</button><button class="group-action" :disabled="selected?.type!=='group'" @click="ungroupSelected">Desagrupar</button></div><span v-if="showToolbarCheckboxes" class="separator" aria-hidden="true"></span><div v-if="showToolbarCheckboxes" class="toolbar-group"><label class="snap" title="Activar o desactivar las colisiones de los elementos opcionales. Vigas y columnas colisionan con otros tipos, pero pueden solaparse entre sí. Un estado mixto indica ajustes individuales."><input :checked="collisionSelection.checked" :indeterminate="collisionSelection.mixed" :aria-checked="collisionSelection.mixed?'mixed':collisionSelection.checked" type="checkbox" @change="changeCollisions"> Colisiones</label><label class="snap" title="Ajustar movimientos y tamaños en pasos de 50 mm; giros en pasos de 15°"><input v-model="state.snap" type="checkbox"> Snap</label><label class="snap" title="Ajustar caras a paredes, suelo y altura de la habitación (60 mm)"><input v-model="state.wallSnap" :disabled="!state.snap" type="checkbox"> Paredes</label></div><span class="separator" aria-hidden="true"></span><div ref="colorControl" class="color-control"><button aria-label="Selector de colores" :title="floorPalette?'Color del suelo':structurePalette?'Color de paredes, vigas y columnas':'Color del elemento seleccionado'" :disabled="!paletteEnabled" :aria-expanded="paletteOpen" aria-controls="toolbar-color-palette" :class="{active:paletteOpen}" @click="paletteOpen=!paletteOpen"><svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linejoin="miter"><path d="m7 7 13-2 8 5-9 17M5 8l10-5 9 18-10 5Z"/><path d="m9 16 11-5"/><circle cx="16" cy="22" r="2"/></svg></button><div v-if="paletteOpen" id="toolbar-color-palette" class="color-palette" role="group" :aria-label="floorPalette?'Color del suelo':structurePalette?'Color de la estructura':'Color del elemento'"><div v-if="structurePalette" class="surface-color-target"><button :aria-pressed="surfaceColorTarget==='walls'" @click="surfaceColorTarget='walls'">Paredes</button><button :disabled="!state.room" :aria-pressed="surfaceColorTarget==='floor'" @click="surfaceColorTarget='floor'">Suelo</button></div><button class="color-swatch reset-color" aria-label="Restaurar color original" title="Restaurar color original" @click="resetPaletteColor"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 5 14 14" stroke="#ff3b30" stroke-width="1.5"/></svg></button><button v-for="color in paletteColors" :key="color.value" class="color-swatch" :style="{backgroundColor:color.value}" :aria-label="color.name" :title="color.name" :aria-pressed="paletteColor?.toLowerCase()===color.value" @click="applyPaletteColor(color.value)"></button></div></div><span class="separator" aria-hidden="true"></span><select v-model="currentView" aria-label="Vista de cámara" @change="changeView"><option>Perspectiva</option><option>Superior</option><option>Frontal</option><option>Lateral</option></select><span v-if="!customEditing" class="separator" aria-hidden="true"></span><button v-if="!customEditing" class="edit-room-button" :class="{active:roomEditorOpen}" :disabled="!state.room" :aria-expanded="roomEditorOpen" aria-controls="room-editor" @click="toggleRoomEditor">{{roomEditorOpen?'Confirmar edición':'Editar estancia'}}</button></div></div></main>
<aside v-if="roomEditorOpen && state.room" id="room-editor" class="properties room-editor" aria-label="Editar estancia"><label v-for="f in roomFields" :key="f.key" class="field">{{f.label}}<div class="number-field"><input type="number" min="1" max="100000" step="50" :value="state.room[f.key]" @focus="checkpoint" @input="e=>editRoom(f.key,input(e))" @blur="e=>resetRoomInput(e,f.key)"><span>mm</span></div></label></aside></div><div v-if="state.error || state.autosaveError" role="alert" class="error">{{state.error || state.autosaveError}}<button @click="state.error='';state.autosaveError=''">Cerrar</button></div><dialog ref="libraryDialog" class="custom-library-dialog" @cancel="libraryOpen=false" @close="libraryOpen=false" aria-labelledby="custom-library-title"><div class="custom-library-heading"><h2 id="custom-library-title">Objetos personalizados</h2><button aria-label="Cerrar objetos personalizados" @click="libraryOpen=false">×</button></div><button class="primary create-custom-button" @click="startCustom()">＋ Crear objeto personalizado</button><p v-if="libraryError" class="library-error" role="alert">{{libraryError}}</p><div v-if="state.customObjects.length" class="custom-library-grid"><div v-for="entry in state.customObjects" :key="entry.id" class="custom-library-card"><button class="custom-library-item" :aria-label="'Añadir '+entry.name" @click="insertCustom(entry.id)"><CustomThumbnail :object="entry.object"/><span>{{entry.name}}</span></button><button class="edit-custom-button" :aria-label="'Editar '+entry.name" :title="'Editar '+entry.name" @click="startCustom(entry.id)"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 3 5 5-12 12-6 1 1-6L16 3Z"/><path d="m13 6 5 5M4 15l5 5"/></svg></button></div></div><p v-else class="muted">Crea tu primer objeto combinando prismas y cilindros.</p></dialog></div>
</template>





